     refilled_at TEXT NOT NULL
   )`,
  `CREATE INDEX IF NOT EXISTS rate_limit_org_key_idx ON rate_limit_buckets (org_id, bucket_key)`,
  `CREATE TABLE IF NOT EXISTS search_index (
