s=open(p).read()
s=s.replace('import { getDb, members, users } from "@/server/db";','import { getDb, memberAbsences, members, users } from "@/server/db";')
s=s.replace('import { toMember, toUser }','import { toMember, toMemberAbsence, toUser }')
s=s.replace('import type { Member, MemberWithUser, Role }','import type { Member, MemberAbsence, MemberWithUser, Role }')
# archiveMember cleanup
old='''  const row = getDb()
    .update(members)
    .set({ ...archivePatch(), status: "suspended" })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}
'''
new='''  const db = getDb();
  const row = db
    .update(members)
    .set({ ...archivePatch(), status: "suspended" })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);

  // Their absence goes with them, and nobody keeps them as a stand-in.
  db.delete(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, row.userId),
      ),
    )
    .run();
  db.update(memberAbsences)
    .set({ delegateUserId: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.delegateUserId, row.userId),
      ),
    )
    .run();

  return toMember(row);
}

/** The stored absence, whether or not it has started or ended. */
export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(
      and(orgPredicate(memberAbsences.orgId, orgId), eq(memberAbsences.userId, userId)),
    )
    .get();
  return row ? toMemberAbsence(row) : null;
}

/** One absence per member: setting again replaces the previous one. */
export async function upsertAbsence(absence: MemberAbsence): Promise<MemberAbsence> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(memberAbsences)
    .values({
      orgId: absence.orgId,
      userId: absence.userId,
      delegateUserId: absence.delegateUserId,
      startsAt: absence.startsAt,
      endsAt: absence.endsAt,
      note: absence.note,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: {
        delegateUserId: absence.delegateUserId,
        startsAt: absence.startsAt,
        endsAt: absence.endsAt,
        note: absence.note,
        updatedAt: stamp,
      },
    })
    .returning()
    .get();
  return toMemberAbsence(row);
}

export async function deleteAbsence(orgId: OrgId, userId: UserId): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(
      and(orgPredicate(memberAbsences.orgId, orgId), eq(memberAbsences.userId, userId)),
    )
    .run();
}
'''
assert old in s
s=s.replace(old,new,1)
open(p,'w').write(s)
EOF

